const incoming = items && items[0] && items[0].json ? items[0].json : {};
const body = incoming.body || incoming;
const availableTime = String(body.available_time || body.availableTime || 'unknown');
const preferredMode = String(body.preferred_mode || body.preferredMode || 'any');
const maxOptions = Math.min(Number(body.max_options || body.maxOptions || 3), 3);
const respectWip = body.respect_wip !== false;
const dryRun = body.dry_run !== false;

const prompt = [
  'Recomienda siguiente trabajo del backlog del proyecto Invernadero Central leyendo el estado versionado actual.',
  `Solicitud: ${body.request || body.message || 'Recomendar siguiente trabajo del backlog'}.`,
  `Tiempo disponible humano: ${availableTime}.`,
  `Modo preferido: ${preferredMode}.`,
  `Maximo de opciones: ${maxOptions}.`,
  `Respetar WIP: ${respectWip}.`,
  'Lee project/backlog/master-backlog.yaml y project/kanban/board.yaml en vivo; no uses snapshots.',
  'Considera prioridad, estado, WIP, dependencias, riesgo, fase del roadmap, rol experto, rol revisor, evidencias faltantes y si necesita refinamiento granular.',
  'Devuelve maximo 3 opciones con backlog_id, title, current_status, priority, role, reviewer_role, why_now, next_step, work_type, blockers y recommendation_warning.',
  'Si WIP esta lleno, recomienda continuar o desbloquear items en IN_PROGRESS/VALIDATION, no jalar trabajo nuevo.',
  'No muevas estados Kanban, no marques DONE, no edites HU congeladas, no inventes evidencia, no hagas commits.',
  'Haz una sola pregunta final al humano: cual opcion quiere tomar ahora.'
].join(' ');

return [{
  json: {
    agent: 'project-backlog',
    workspace: 'central',
    prompt,
    mode: 'backlog-recommendation',
    approval_required: true,
    dry_run: dryRun,
    metadata: {
      task_id: 'WF-BACKLOG-RECOMMEND-001',
      agent_id: 'AGENT-BKL-001',
      available_time: availableTime,
      preferred_mode: preferredMode,
      max_options: maxOptions,
      respect_wip: respectWip,
      requested_by: body.requested_by || 'chat-gateway'
    }
  }
}];
